def _looks_like_typing_cast(node: Call) -> bool:
    """Check if the node represents a call to typing.cast."""
    if not isinstance(node, Call) or not node.args or len(node.args) != 2:
        return False

    func = node.func
    if isinstance(func, Name):
        return func.name == "cast"
    if isinstance(func, Attribute):
        return func.attrname == "cast" and isinstance(func.expr, Name) and func.expr.name == "typing"
    return False


def infer_typing_cast(
    node: Call, ctx: context.InferenceContext | None = None
) -> Iterator[InferenceResult]:
    """Infer typing.cast call.

    typing.cast(typ, val) returns val unchanged, but we need to make sure
    that each call with different arguments is inferred separately.
    """
    if not node.args or len(node.args) != 2:
        raise UseInferenceDefault

    # The second argument is the value being cast
    val_arg = node.args[1]

    # Prevent caching of the inference result by setting _explicit_inference
    # with a lambda that directly infers the value argument
    def _infer_cast_value(node, context):
        return val_arg.infer(context=context)

    # Set the explicit inference function to avoid caching
    node._explicit_inference = _infer_cast_value

    # Return the inferred value
    return val_arg.infer(context=ctx)


