def _looks_like_typing_cast(node: Call) -> bool:
    """Check if the node represents a call to typing.cast."""
    if not isinstance(node, Call):
        return False

    # Handle both positional and keyword arguments
    if node.args and len(node.args) == 2:
        pass  # Standard case with 2 positional args
    elif not node.args and node.keywords and len(node.keywords) == 2:
        # Check if we have typ and val keyword arguments
        keyword_names = {kw.arg for kw in node.keywords if kw.arg}
        if keyword_names != {"typ", "val"}:
            return False
    else:
        return False

    func = node.func
    if isinstance(func, Name):
        return func.name == "cast"
    if isinstance(func, Attribute):
        return func.attrname == "cast" and isinstance(func.expr, Name) and func.expr.name == "typing"
    return False


def infer_typing_cast(
    node: Call, ctx: context.InferenceContext | None = None
) -> Iterator[InferenceResult]:
    """Infer typing.cast call.

    typing.cast(typ, val) returns val unchanged, but we need to make sure
    that each call with different arguments is inferred separately.
    """
    # Get the value argument (second positional arg or 'val' keyword arg)
    val_arg = None
    if node.args and len(node.args) == 2:
        val_arg = node.args[1]
    elif node.keywords:
        for kw in node.keywords:
            if kw.arg == "val":
                val_arg = kw.value
                break

    if val_arg is None:
        raise UseInferenceDefault

    # Create a fresh context for each inference to avoid caching issues
    if ctx is not None:
        ctx = ctx.clone()

    # Return the inferred value directly without caching
    return val_arg.infer(context=ctx)
